/**
 * Baidu Qianfan API — Token Authentication Example
 * ================================================
 * This module provides a production-ready implementation of Baidu Qianfan API
 * authentication with automatic token caching and refresh.
 * 
 * For production use:
 * - Tokens are cached for 30 days
 * - Refresh is triggered 1 day before expiry
 * - Token is passed via Authorization header (Bearer token)
 * 
 * @author Assistant
 * @created 2025-06-08
 */

const axios = require('axios');


class TokenCache {
    /**
     * Access token cache with automatic refresh.
     * 
     * Token validity: 2,592,000 seconds (30 days)
     * Refresh threshold: 86,400 seconds (1 day) before expiry
     */

    static TOKEN_ENDPOINT = 'https://aip.baidubce.com/oauth/3.0/token';
    static TOKEN_VALIDITY = 2592000; // 30 days in seconds
    static REFRESH_THRESHOLD = 86400; // 1 day in seconds

    constructor(apiKey, secretKey) {
        this.apiKey = apiKey;
        this.secretKey = secretKey;
        this.token = null;
        this.expiresAt = null; // Unix timestamp in seconds
        this._lastRequestTime = null;
    }

    _getCurrentTime() {
        return Date.now() / 1000; // Convert to seconds
    }

    isValid() {
        if (this.token === null) {
            return false;
        }
        const now = this._getCurrentTime();
        return now < this.expiresAt - this.REFRESH_THRESHOLD;
    }

    async _requestToken() {
        const params = new URLSearchParams({
            grant_type: 'client_credentials',
            client_id: this.apiKey,
            client_secret: this.secretKey,
            timestamp: Math.floor(this._getCurrentTime() * 1000).toString()
        });

        const headers = {
            'Content-Type': 'application/x-www-form-urlencoded'
        };

        const response = await axios.post(
            this.constructor.TOKEN_ENDPOINT,
            params,
            {
                headers,
                timeout: 30000,
                validateStatus: (status) => status >= 200 && status < 400
            }
        );

        return response.data;
    }

    getAccessToken(forceRefresh = false) {
        if (!forceRefresh && this.isValid() && this.token !== null) {
            return { token: this.token, refreshed: false };
        } else {
            return this._requestToken().then(result => {
                const accessToken = result.access_token;
                const expiresIn = result.expires_in || this.constructor.TOKEN_VALIDITY;

                this.token = accessToken;
                this.expiresAt = this._getCurrentTime() + expiresIn;

                return { token: accessToken, refreshed: true };
            }).catch(e => {
                return { token: null, refreshed: true };
            });
        }
    }

    async refreshAccessToken() {
        return this.getAccessToken(true);
    }

    reset() {
        this.token = null;
        this.expiresAt = null;
        this._lastRequestTime = null;
    }

    isForcedRefresh() {
        return !this.isValid();
    }
}


class TokenError extends Error {
    constructor(message, originalError = null) {
        super(`${message}: ${originalError ? originalError.message : ''}`);
        this.message = message;
        this.originalError = originalError;
    }
}


class ApiError extends Error {
    /**
     * Custom exception for API errors.
     * 
     * @param {string} errorCode - Error code from Baidu API
     * @param {string} message - Error message
     * @param {number} httpStatus - HTTP status code (optional, for 4xx/5xx)
     */
    constructor(errorCode, message, httpStatus = 0) {
        super(`API Error [code=${errorCode}, status=${httpStatus}]: ${message}`);
        this.errorCode = errorCode;
        this.message = message;
        this.httpStatus = httpStatus;
    }
}


class QianfanClient {
    /**
     * Baidu Qianfan API client with authentication, token management, and error handling.
     * 
     * Features:
     * - Automatic token caching and refresh (30 day validity, refresh 1 day early)
     * - Exponential backoff for retries
     * - Intelligent error handling with specific actions per error code
     * - Token passed via Authorization header (security best practice)
     */

    // API endpoints
    static TOKEN_ENDPOINT = 'https://aip.baidubce.com/oauth/3.0/token';
    CHAT_ENDPOINT = 'https://aip.baidubce.com/rpc/2.0/ai_custom/v1/wenxinworkshop/chat/completions';

    // Default configuration
    static DEFAULT_TIMEOUT = 15000; // milliseconds
    static DEFAULT_MAX_RETRIES = 3;

    // Retry configuration
    static DEFAULT_RETRY_CONFIG = {
        initialDelayMs: 200,
        maxDelayMs: 5000,
        backoffMultiplier: 1.5
    };

    constructor(apiKey, secretKey, options = {}) {
        this.apiKey = apiKey;
        this.secretKey = secretKey;

        const {
            timeout = this.constructor.DEFAULT_TIMEOUT,
            maxRetries = this.constructor.DEFAULT_MAX_RETRIES,
            retryConfig = {}
        } = options;

        this.tokenCache = new TokenCache(apiKey, secretKey);

        // Set request timeout
        this.timeout = timeout;

        // Set max retries
        this.maxRetries = maxRetries;

        // Merge retry configuration
        this.retryConfig = {
            ...this.constructor.DEFAULT_RETRY_CONFIG,
            ...retryConfig
        };

        // Initial token
        this._fetchTokenIfNeeded();
    }

    _fetchTokenIfNeeded() {
        const tokenCache = this.tokenCache;
        if (tokenCache.token === null || !tokenCache.isValid()) {
            tokenCache._forceRefresh = true;
            tokenCache.getAccessToken(true);
            tokenCache._forceRefresh = false;
        }
    }

    _calculateBackoff(retryCount) {
        /**
         * Calculate exponential backoff delay in milliseconds.
         * 
         * Formula: delay = min(initialDelay * multiplier^(retryCount-1), maxDelay)
         */
        const delayMs = this.retryConfig.initialDelayMs * 
            Math.pow(this.retryConfig.backoffMultiplier, retryCount - 1);
        return Math.min(delayMs, this.retryConfig.maxDelayMs);
    }

    _getTimestampHeader() {
        return new Date().toUTCString();
    }

    /**
     * Get or refresh the access token.
     * 
     * @param {boolean} forceRefresh - If true, always request new token; otherwise use cache
     * @returns {string|null} Access token or null if unavailable
     */
    getAccessToken(forceRefresh = false) {
        const tokenCache = this.tokenCache;

        if (forceRefresh || !tokenCache.isValid()) {
            return tokenCache.getAccessToken(forceRefresh)
                .then(result => {
                    tokenCache._forceRefresh = false;
                    return result;
                })
                .then(result => {
                    if (result.token) {
                        return result.token;
                    }
                    return null;
                });
        }
        return this.tokenCache.token;
    }

    /**
     * Manually refresh the access token.
     * 
     * @returns {string|null} Access token or null if refresh failed
     */
    refreshAccessToken() {
        return this.tokenCache.refreshAccessToken()
            .then(result => {
                this.tokenCache._forceRefresh = false;
                return result.token;
            });
    }

    resetTokenCache() {
        this.tokenCache.reset();
    }

    /**
     * Check if current cached token is valid.
     * 
     * @returns {boolean} True if token is valid
     */
    checkTokenValidity() {
        return this.tokenCache.isValid();
    }

    /**
     * Get token expiry timestamp.
     * 
     * @returns {number|null} Expiry timestamp in seconds (Unix time)
     */
    getTokenExpiry() {
        return this.tokenCache.expiresAt;
    }

    /**
     * Check if token needs to be refreshed.
     * 
     * @returns {boolean} True if token needs refresh
     */
    isNeedingRefresh() {
        return !this.checkTokenValidity();
    }

    /**
     * Build request headers with authentication.
     * 
     * Uses Authorization header (Bearer token) instead of query parameter
     * for security reasons (avoids token in URL logs).
     * 
     * @param {string} accessToken - Valid access token
     * @returns {object} Headers object
     */
    _buildHeaders(accessToken) {
        const timestamp = this._getTimestampHeader();

        return {
            'Authorization': `Bearer ${accessToken}`,
            'Content-Type': 'application/json',
            'X-Bce-Date': timestamp
        };
    }

    /**
     * Send chat completion request with automatic token management and retry logic.
     * 
     * @param {array} messages - Array of message objects with role and content
     * @param {string} model - Model name (default: "ernie-bot")
     * @param {number} temperature - Sampling temperature 0.0-1.0 (default: 0.7)
     * @param {number} topP - Top-p nucleus sampling 0.0-1.0 (default: 0.7)
     * @param {boolean} stream - Whether to use streaming (default: false)
     * @param {boolean} retryOnError - Whether to retry on transient errors (default: true)
     * 
     * @returns {object|AsyncGenerator} Response object or streaming chunks
     * 
     * @throws {ApiError} On persistent error after all retries
     */
    async chatCompletion(messages, options = {}) {
        const {
            model = 'ernie-bot',
            temperature = 0.7,
            topP = 0.7,
            stream = false,
            retryOnError = true
        } = options;

        // Get or refresh token if needed
        const access_token = await this.getAccessToken(forceRefresh = true);
        if (access_token === null) {
            throw new ApiError('TOKEN_UNAVAILABLE', 'Failed to obtain access token', 401);
        }

        const timestamp = this._getTimestampHeader();

        const headers = this._buildHeaders(access_token);

        const data = {
            messages: messages,
            model: model,
            temperature: temperature,
            top_p: topP,
            stream: stream
        };

        let requestCount = 0;

        while (requestCount < this.maxRetries) {
            try {
                const response = await axios.post(
                    this.CHAT_ENDPOINT,
                    data,
                    {
                        headers,
                        timeout: this.timeout,
                        validateStatus: (status) => status >= 200 && status < 400
                    }
                );

                const content = response.data;
                requestCount++;

                if (stream) {
                    return this._handleStreamingResponse(content);
                }

                const result = content.result;
                const usage = content.usage;

                return { result, usage, request_count: requestCount };

            } catch (e) {

                if (e.response) {
                    // API returned an error code (200 status with error in body)
                    const errorData = e.response.data;
                    const errorCode = errorData?.error_code;
                    const errorMessage = errorData?.error?.content || 
                                        errorData?.result?.content || 
                                        e.message;

                    if (!retryOnError) {
                        throw new ApiError(errorCode, errorMessage, e.response.status);
                    }

                    if (errorCode === '110' || errorCode === '111') {
                        // Token invalid or expired - refresh token
                        console.log(`[WARN] Token error (code ${errorCode}): ${errorMessage}`);
                        this.resetTokenCache();

                        access_token = await this.getAccessToken(forceRefresh = true);
                        if (access_token === null) {
                            throw new ApiError('TOKEN_REFRESH_FAILED', 'Failed to refresh token', 401);
                        }
                        headers = this._buildHeaders(access_token);
                        requestCount++;
                        await this._wait(this._calculateBackoff(requestCount));
                        continue;
                    } else if (errorCode === '17') {
                        // Daily quota limit - cannot retry
                        throw new ApiError('QUOTA_EXCEEDED', 'Daily API quota limit reached', 429);
                    } else if (errorCode === '18') {
                        // QPS limit - retry with backoff
                        const delayMs = this._calculateBackoff(requestCount);
                        console.log(`[WARN] Rate limited (code ${errorCode}), waiting ${delayMs}ms`);
                        await this._wait(delayMs);
                        requestCount++;
                        continue;
                    } else if (errorCode === '282000') {
                        // Server error - retry with backoff
                        const delayMs = this._calculateBackoff(requestCount);
                        console.log(`[WARN] Server error (code ${errorCode}), retrying`);
                        await this._wait(delayMs);
                        requestCount++;
                        continue;
                    } else if (errorCode === '336001' || errorCode === '336003') {
                        // Parameter or payload error - should not retry
                        const errorReason = errorData.error.reason || 'Invalid request';
                        throw new ApiError(errorCode, errorReason, 400);
                    } else {
                        throw new ApiError(errorCode, errorMessage, e.response.status);
                    }

                } else if (e.code === 'ECONNABORTED') {
                    // Timeout
                    const delayMs = this._calculateBackoff(requestCount);
                    console.log(`[WARN] Request timeout, retry ${requestCount + 1}/${this.maxRetries} after ${delayMs}ms`);
                    await this._wait(delayMs);
                    requestCount++;
                    continue;

                } else if (e.code === 'ECONNREFUSED' || e.code === 'ECONNRESET') {
                    // Connection error
                    const delayMs = this._calculateBackoff(requestCount);
                    console.log(`[WARN] Connection error, retry ${requestCount + 1}/${this.maxRetries} after ${delayMs}ms`);
                    await this._wait(delayMs);
                    requestCount++;
                    continue;

                } else {
                    // Unknown error
                    throw new ApiError('UNKNOWN_ERROR', `Unexpected error: ${e.message}`, 0);
                }
            }
        }

        // Max retries exceeded
        throw new ApiError('MAX_RETRIES_EXCEEDED', `Maximum retries (${this.maxRetries}) exceeded`, 500);
    }

    /**
     * Handle streaming response (Server-Sent Events).
     * 
     * Returns async generator that yields chunks.
     * 
     * @param {string} content - Raw SSE content
     * @returns {AsyncGenerator} Generator yielding { id, choices: [{delta, role}] }
     */
    async *_handleStreamingResponse(content) {
        for (const line of content.split('\n')) {
            line = line.trim();
            if (line.startsWith('data:')) {
                const data = line.slice(5).trim(); // Remove 'data: ' prefix
                if (data === '[DONE]') {
                    yield { choices: [{ delta: '', role: 'assistant' }], id: 'DONE' };
                } else {
                    try {
                        const chunk = JSON.parse(data);
                        yield chunk;
                    } catch (e) {
                        // Skip invalid lines
                    }
                }
            }
        }
    }

    /**
     * Wait for specified milliseconds.
     * 
     * @param {number} ms - Milliseconds to wait
     */
    async _wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}


/**
 * Main example script for Baidu Qianfan API integration.
 */
async function main() {
    /**
     * Demonstrates:
     * 1. Loading credentials from environment
     * 2. Initializing the client
     * 3. Checking token status
     * 4. Performing chat completion
     * 5. Handling errors appropriately
     */

    // Load credentials from environment variables (do NOT hardcode!)
    const apiKey = process.env.BAIDU_API_KEY;
    const secretKey = process.env.BAIDU_SECRET_KEY;

    if (!apiKey || !secretKey) {
        console.error('Error: BAIDU_API_KEY and BAIDU_SECRET_KEY must be set in environment variables');
        console.error('');
        console.error('Usage:');
        console.error('  export BAIDU_API_KEY="your_api_key"');
        console.error('  export BAIDU_SECRET_KEY="your_secret_key"');
        console.error('');
        console.error('Then run: node auth_example.js');
        process.exit(1);
    }

    // Initialize client
    const client = new QianfanClient(apiKey, secretKey);

    console.log('='.repeat(60));
    console.log('Baidu Qianfan API - Token Authentication Example');
    console.log('='.repeat(60));
    console.log('');

    // Display token status
    if (client.checkTokenValidity()) {
        const token = client.tokenCache.token;
        const expiry = client.getTokenExpiry();
        const now = Date.now() / 1000;
        const expiresInHours = ((expiry - now) / 3600).toFixed(0);

        console.log('Token Status: VALID (cached)');
        console.log(`Token: ${'*'.repeat(10)}${token.slice(token.length - 15)}...`);
        console.log(`Expires in: ${expiresInHours} hours`);
        console.log(`Refresh threshold: 24 hours`);
        console.log('');
    } else {
        console.log('Token Status: NONE or EXPIRED');
        console.log('Fetching new token...');
        console.log('');
    }

    // Example: Get a new access token (force refresh)
    console.log('Action: Fetching access token...');
    const token = await client.getAccessToken(forceRefresh = true);
    if (token) {
        console.log(`✓ Token obtained: ${'*'.repeat(10)}${token.slice(token.length - 20)}...`);
        console.log('');
    } else {
        console.error('✗ Failed to obtain access token');
        process.exit(1);
    }

    // Example chat completion
    console.log('='.repeat(60));
    console.log('Testing chat completion...');
    console.log('='.repeat(60));
    console.log('');

    const messages = [
        { role: 'user', content: '你好，请介绍一下百度千帆大模型平台。' }
    ];

    try {
        const response = await client.chatCompletion(messages);

        console.log('Response received!');
        console.log('');
        console.log('Result:', response.result);
        if (response.usage) {
            console.log(`Usage: ${response.usage.total_tokens} tokens`);
        }

        // Display request count
        if (response.request_count) {
            console.log(`Request count: ${response.request_count}`);
        }

    } catch (e) {
        console.error('');
        console.error('='.repeat(60));
        console.error('Error occurred:');
        console.error('='.repeat(60));
        console.error('');
        console.error(e.message);
        console.log('');
        console.error(`Error Code: ${e.errorCode}`);
        console.error(`HTTP Status: ${e.httpStatus}`);
        console.log('');

        console.log('Recommended action:');
        if (e.httpStatus === 401) {
            console.log('  → Refresh token immediately');
        } else if (e.httpStatus === 429) {
            if (e.errorCode === '17') {
                console.log('  → Wait until tomorrow (daily quota exceeded)');
            } else if (e.errorCode === '18') {
                console.log('  → Rate limited, wait and retry (client will auto-retry with backoff)');
            }
        } else if (e.httpStatus === 500) {
            if (e.errorCode === '282000') {
                console.log('  → Server error, retry or contact support');
            } else if (e.errorCode === 'MAX_RETRIES_EXCEEDED') {
                console.log('  → Server error, max retries exceeded, contact support');
            }
        } else {
            console.log(`  → Error ${e.errorCode}, check request parameters`);
        }

        process.exit(1);
    }

    console.log('');
    console.log('='.repeat(60));
    console.log('✓ Chat completion successful!');
    console.log('='.repeat(60));
    console.log('');

    // Example: Check if token needs refresh
    console.log('Token validity check:');
    const needsRefresh = client.isNeedingRefresh();
    if (needsRefresh) {
        console.log('  → Token needs refresh, refresh now');
        const newToken = await client.refreshAccessToken();
        if (newToken) {
            console.log('  → Token refreshed successfully');
        }
    } else {
        console.log('  → Token is valid');
    }
    console.log('');
}


// Export for module usage
module.exports = {
    TokenCache,
    QianfanClient,
    ApiError,
    TokenError
};


// Run if executed directly
if (require.main === module) {
    main().catch(e => {
        console.error('Fatal error:', e.message);
        process.exit(1);
    });
}
