        return Math.min(delayMs, this.retryConfig.maxDelayMs);
    }

    _getTimestampHeader() {
        return new Date().toUTCString();
    }

    /**
     * Get or refresh the access token.
     * 
     * @param {boolean} forceRefresh - If true, always request new token; otherwise use cache
     * @returns {Promise<string|null>} Access token or null if unavailable
     */
    async getAccessToken(forceRefresh = false) {
        const tokenCache = this.tokenCache;

        if (forceRefresh || !tokenCache.isValid()) {
            const result = await tokenCache.getAccessToken(forceRefresh);
            tokenCache._forceRefresh = false;
            if (result.token) {
                return result.token;
            }
            return null;
        }
        return this.tokenCache.token;
    }

    /**
     * Manually refresh the access token.
     * 
     * @returns {Promise<string|null>} Access token or null if refresh failed
     */
    async refreshAccessToken() {
        return this.tokenCache.refreshAccessToken()
            .then(result => {
                this.tokenCache._forceRefresh = false;
                return result.token;
            });
    }

    resetTokenCache() {
        this.tokenCache.reset();
    }

    /**
     * Check if current cached token is valid.
     * 
     * @returns {boolean} True if token is valid
     */
    checkTokenValidity() {
        return this.tokenCache.isValid();
    }

    /**
     * Get token expiry timestamp.
     * 
     * @returns {number|null} Expiry timestamp in seconds (Unix time)
     */
    getTokenExpiry() {
        return this.tokenCache.expiresAt;
    }

    /**
     * Check if token needs to be refreshed.
     * 
     * @returns {boolean} True if token needs refresh
     */
    isNeedingRefresh() {
        return !this.checkTokenValidity();
    }

    /**
     * Build request headers with authentication.
     * 
     * Uses Authorization header (Bearer token) instead of query parameter
     * for security reasons (avoids token in URL logs).
     * 
     * @param {string} accessToken - Valid access token
     * @returns {object} Headers object
     */
    _buildHeaders(accessToken) {
        const timestamp = this._getTimestampHeader();

        return {
            'Authorization': `Bearer ${accessToken}`,
            'Content-Type': 'application/json',
            'X-Bce-Date': timestamp
        };
    }

    /**
     * Send chat completion request with automatic token management and retry logic.
     * 
     * @param {array} messages - Array of message objects with role and content
     * @param {string} model - Model name (default: "ernie-bot")
     * @param {number} temperature - Sampling temperature 0.0-1.0 (default: 0.7)
     * @param {number} topP - Top-p nucleus sampling 0.0-1.0 (default: 0.7)
     * @param {boolean} stream - Whether to use streaming (default: false)
     * @param {boolean} retryOnError - Whether to retry on transient errors (default: true)
     * 
     * @returns {object|AsyncGenerator} Response object or streaming chunks
     * 
     * @throws {ApiError} On persistent error after all retries
     */
    async chatCompletion(messages, options = {}) {
        const {
            model = 'ernie-bot',
            temperature = 0.7,
            topP = 0.7,
            stream = false,
            retryOnError = true
        } = options;

        // Get or refresh token if needed
        const access_token = await this.getAccessToken(forceRefresh = true);
        if (access_token === null) {
            throw new ApiError('TOKEN_UNAVAILABLE', 'Failed to obtain access token', 401);
        }

        const timestamp = this._getTimestampHeader();

        const headers = this._buildHeaders(access_token);

        const data = {
            messages: messages,
            model: model,
            temperature: temperature,
            top_p: topP,
            stream: stream
        };

        let requestCount = 0;

        while (requestCount < this.maxRetries) {
            try {
                const response = await axios.post(
                    this.CHAT_ENDPOINT,
                    data,
                    {
                        headers,
                        timeout: this.timeout,
                        validateStatus: (status) => status >= 200 && status < 400
                    }
                );

                const content = response.data;
                requestCount++;

                if (stream) {
                    return this._handleStreamingResponse(content);
                }

                const result = content.result;
                const usage = content.usage;

                return { result, usage, request_count: requestCount };

            } catch (e) {

                if (e.response) {
                    // API returned an error code (200 status with error in body)
                    const errorData = e.response.data;
                    const errorCode = errorData?.error_code;
                    const errorMessage = errorData?.error?.content || 
                                        errorData?.result?.content || 
                                        e.message;

                    if (!retryOnError) {
                        throw new ApiError(errorCode, errorMessage, e.response.status);
                    }

                    if (errorCode === '110' || errorCode === '111') {
                        // Token invalid or expired - refresh token
                        console.log(`[WARN] Token error (code ${errorCode}): ${errorMessage}`);
                        this.resetTokenCache();

                        access_token = await this.getAccessToken(forceRefresh = true);
                        if (access_token === null) {
                            throw new ApiError('TOKEN_REFRESH_FAILED', 'Failed to refresh token', 401);
                        }
                        headers = this._buildHeaders(access_token);
                        requestCount++;
                        await this._wait(this._calculateBackoff(requestCount));
                        continue;
                    } else if (errorCode === '17') {
                        // Daily quota limit - cannot retry
                        throw new ApiError('QUOTA_EXCEEDED', 'Daily API quota limit reached', 429);
                    } else if (errorCode === '18') {
                        // QPS limit - retry with backoff
                        const delayMs = this._calculateBackoff(requestCount);
                        console.log(`[WARN] Rate limited (code ${errorCode}), waiting ${delayMs}ms`);
                        await this._wait(delayMs);
                        requestCount++;
                        continue;
                    } else if (errorCode === '282000') {
                        // Server error - retry with backoff
                        const delayMs = this._calculateBackoff(requestCount);
                        console.log(`[WARN] Server error (code ${errorCode}), retrying`);
                        await this._wait(delayMs);
                        requestCount++;
                        continue;
                    } else if (errorCode === '336001' || errorCode === '336003') {
                        // Parameter or payload error - should not retry
                        const errorReason = errorData.error.reason || 'Invalid request';
                        throw new ApiError(errorCode, errorReason, 400);
                    } else {
                        throw new ApiError(errorCode, errorMessage, e.response.status);
                    }

                } else if (e.code === 'ECONNABORTED') {
                    // Timeout
                    const delayMs = this._calculateBackoff(requestCount);
                    console.log(`[WARN] Request timeout, retry ${requestCount + 1}/${this.maxRetries} after ${delayMs}ms`);
                    await this._wait(delayMs);
                    requestCount++;
                    continue;

                } else if (e.code === 'ECONNREFUSED' || e.code === 'ECONNRESET') {
                    // Connection error
                    const delayMs = this._calculateBackoff(requestCount);
                    console.log(`[WARN] Connection error, retry ${requestCount + 1}/${this.maxRetries} after ${delayMs}ms`);
                    await this._wait(delayMs);
                    requestCount++;
                    continue;

                } else {
                    // Unknown error
                    throw new ApiError('UNKNOWN_ERROR', `Unexpected error: ${e.message}`, 0);
                }
            }
        }

        // Max retries exceeded
        throw new ApiError('MAX_RETRIES_EXCEEDED', `Maximum retries (${this.maxRetries}) exceeded`, 500);
    }

    /**
     * Handle streaming response (Server-Sent Events).
     * 
     * Returns async generator that yields chunks.
     * 
     * @param {string} content - Raw SSE content
     * @returns {AsyncGenerator} Generator yielding { id, choices: [{delta, role}] }
     */
    async *_handleStreamingResponse(content) {
        for (const line of content.split('\n')) {
            line = line.trim();
            if (line.startsWith('data:')) {
                const data = line.slice(5).trim(); // Remove 'data: ' prefix
                if (data === '[DONE]') {
                    yield { choices: [{ delta: '', role: 'assistant' }], id: 'DONE' };
                } else {
                    try {
                        const chunk = JSON.parse(data);
                        yield chunk;
                    } catch (e) {
                        // Skip invalid lines
                    }
                }
            }
        }
    }

    /**
     * Wait for specified milliseconds.
     * 
     * @param {number} ms - Milliseconds to wait
     */
    async _wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}


